actions.script:
for (def gl in glAccountList) { def params = [glAccountId: gl.glAccountId, organizationPartyId: organizationPartyId] if (timePeriodId) params.timePeriodId = timePeriodId
def bal = 0.0 try { def result = ec.service.sync().name("mantle.ledger.LedgerServices.get#GlAccountBalance") .parameters(params).call() bal = result?.balance ?: 0.0 } catch (Exception e) { // Account may have no transactions }
if (bal != 0) { def className = gl.glAccountClassEnumId ?: '' className = className.replaceAll('GlcNet', '').replaceAll('Glc', '').replaceAll(/([A-Z])/, ' $1').trim()
trialBalanceRows.add([ accountCode: gl.accountCode, accountName: gl.accountName, glAccountId: gl.glAccountId, className: className, balance: bal ])
if (bal >= 0) totalDebit += bal else totalCredit += -bal } }
if (trialBalanceRows.isEmpty()) { // Demo data for display trialBalanceRows = [ [accountCode:'1000', accountName:'Cash in Hand', className:'Asset', balance:285000.00], [accountCode:'1100', accountName:'Bank Account - HDFC', className:'Asset', balance:1450000.00], [accountCode:'1200', accountName:'Accounts Receivable', className:'Asset', balance:875000.00], [accountCode:'1300', accountName:'Inventory', className:'Asset', balance:1250000.00], [accountCode:'1500', accountName:'Property, Plant & Equipment', className:'Asset', balance:3200000.00], [accountCode:'1510', accountName:'Accumulated Depreciation', className:'Asset', balance:-480000.00], [accountCode:'2000', accountName:'Accounts Payable', className:'Liability', balance:-650000.00], [accountCode:'2100', accountName:'GST Payable', className:'Liability', balance:-125000.00], [accountCode:'2200', accountName:'Employee Payables', className:'Liability', balance:-320000.00], [accountCode:'2500', accountName:'Long-Term Loan', className:'Liability', balance:-1200000.00], [accountCode:'3000', accountName:'Share Capital', className:'Equity', balance:-3000000.00], [accountCode:'3100', accountName:'Retained Earnings', className:'Equity', balance:-785000.00], [accountCode:'4000', accountName:'Sales Revenue', className:'Revenue', balance:-2800000.00], [accountCode:'4100', accountName:'Service Income', className:'Revenue', balance:-450000.00], [accountCode:'4900', accountName:'Interest Income', className:'Income', balance:-35000.00], [accountCode:'5000', accountName:'Cost of Goods Sold', className:'Expense', balance:1650000.00], [accountCode:'6000', accountName:'Salaries & Wages', className:'Expense', balance:850000.00], [accountCode:'6100', accountName:'Rent Expense', className:'Expense', balance:120000.00], [accountCode:'6200', accountName:'Utilities', className:'Expense', balance:45000.00], [accountCode:'6300', accountName:'Marketing Expense', className:'Expense', balance:85000.00], [accountCode:'7000', accountName:'Depreciation Expense', className:'Expense', balance:60000.00], [accountCode:'7100', accountName:'Bank Charges', className:'Expense', balance:15000.00], [accountCode:'7200', accountName:'Professional Fees', className:'Expense', balance:-10000.00] ] totalDebit = 0.0 totalCredit = 0.0 for (def r : trialBalanceRows) { if (r.balance >= 0) totalDebit += r.balance else totalCredit += -r.balance } showDemo = true }
